<?php
declare(strict_types=1);
namespace App\Application\Website;
use App\Application\Platform\{PlatformOwnerAccess,PlatformStore,PlatformViolation,BusinessActivation};
// Author by Lab | zefry
final readonly class WebsiteManagement {
    public function __construct(private PlatformOwnerAccess $access,private PlatformStore $platform,private WebsiteStore $store){}
    public function editor(string $slug):array{$this->access->require();return ['page'=>$this->store->draft(WebsiteContent::slug($slug)),'pages'=>$this->store->listing(),'revisions'=>$this->store->revisions($slug)];}
    public function preview(string $slug):array{$this->access->require();$p=$this->store->draft(WebsiteContent::slug($slug));return $p+['digest'=>hash('sha256',json_encode($p['document'],JSON_THROW_ON_ERROR))];}
    public function command(string $slug,array $in):array{$owner=$this->access->require();$slug=WebsiteContent::slug($slug);$action=$in['action']??null;$fields=match($action){'save'=>['action','version','operation_id','document'],'publish'=>['action','version','operation_id','digest','reviewed'],'restore'=>['action','version','operation_id','revision'],default=>throw new PlatformViolation('INVALID_ACTION')};if(array_diff(array_keys($in),$fields)||!is_int($in['version']??null)||$in['version']<0)throw new PlatformViolation('INVALID_FIELDS');$op=BusinessActivation::text($in['operation_id']??null,128);if(!preg_match('/\A[a-zA-Z0-9_-]{8,128}\z/',$op))throw new PlatformViolation('INVALID_OPERATION');$actor=$owner->tenantId()->value().'/'.$owner->identityId()->value();return $this->platform->once($actor,$op,['slug'=>$slug,'input'=>$in],function()use($in,$slug,$action,$actor):array{if($action==='save'){if(!is_array($in['document']??null))throw new PlatformViolation('INVALID_CONTENT');$r=$this->store->save($slug,$in['version'],WebsiteContent::document($in['document'],$this->store));}elseif($action==='publish'){if(($in['reviewed']??false)!==true)throw new PlatformViolation('PREVIEW_REQUIRED');$r=$this->store->publish($slug,$in['version'],WebsiteContent::text($in['digest']??'',64),$actor);}else $r=$this->store->restore($slug,$in['version'],WebsiteContent::text($in['revision']??'',32));$this->platform->audit($actor,'website.'.$action,substr(hash('sha256',$slug),0,32),'Page: '.$slug,time());return $r;});}
    public function upload(string $bytes):array{$owner=$this->access->require();if(strlen($bytes)>3*1024*1024||strlen($bytes)<12)throw new PlatformViolation('IMAGE_TOO_LARGE',413);$info=@getimagesizefromstring($bytes);if($info===false||!in_array($info['mime'],['image/png','image/jpeg','image/webp'],true)||$info[0]>6000||$info[1]>6000||$info[0]*$info[1]>20000000)throw new PlatformViolation('INVALID_IMAGE');$id=substr(hash('sha256',$bytes),0,32);$actor=$owner->tenantId()->value().'/'.$owner->identityId()->value();return $this->platform->once($actor,'image-'.$id,['sha256'=>hash('sha256',$bytes)],function()use($id,$info,$bytes,$actor):array{$this->store->putMedia($id,$info['mime'],$bytes,$actor);$this->platform->audit($actor,'website.image',$id,'Uploaded website image',time());return ['id'=>$id];});}
    public function register(array $in):array{if(array_diff(array_keys($in),['name','email','phone','business_type','locale','consent','marketing_consent','website']))throw new PlatformViolation('INVALID_FIELDS');if(($in['website']??'')!=='')return ['status'=>'received'];if(($in['consent']??false)!==true)throw new PlatformViolation('CONSENT_REQUIRED');$clean=['name'=>BusinessActivation::text($in['name']??null,160),'email'=>BusinessActivation::email($in['email']??null),'phone'=>WebsiteContent::text($in['phone']??'',24),'business_type'=>$in['business_type']??'retail','locale'=>$in['locale']??'id'];if(!preg_match('/\A\+?[0-9 ()-]{7,24}\z/',$clean['phone'])||!in_array($clean['business_type'],['retail','food','services','other'],true)||!in_array($clean['locale'],['id','en'],true))throw new PlatformViolation('INVALID_FIELDS');if(isset($in['marketing_consent'])&&!is_bool($in['marketing_consent']))throw new PlatformViolation('INVALID_FIELDS');$clean['marketing_consent']=($in['marketing_consent']??false)===true;$hash=hash('sha256',strtolower($clean['email']));return $this->platform->once('public-registration',$hash,['email_hash'=>$hash],function()use($clean):array{$this->store->registration($clean);return ['status'=>'received'];});}
}
